def span(name):
 start=next(i for i,l in enumerate(lines)if re.search(r'\bfn '+re.escape(name)+r'\b',l));depth=0;seen=False
 for i in range(start,len(lines)):
  line=lines[i].split('//')[0];line=re.sub(r'"(?:\\.|[^"\\])*"','""',line)
  for c in line:
   if c=='{':depth+=1;seen=True
   if c=='}':depth-=1
  if seen and depth==0:return start+1,i+1
 raise ValueError(name)
